package com.iatros.backend.document;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where document bytes live (decisions.md D-032). Keys are generated by the server and never derived from client
 * input. Implementations must not overwrite an existing key.
 */
public interface DocumentStorage {

	void store(String key, InputStream content) throws IOException;

	/** The stored bytes; the caller closes the stream. */
	InputStream open(String key) throws IOException;

	/** Removes the bytes if present. Used only to clean up after a failed upload. */
	void delete(String key) throws IOException;

}
